<script>
(()=>{const overlays=document.querySelectorAll('.atlas-inscripciones ~ .ai-overlay');let previousFocus=null;document.querySelectorAll('[data-ai-open]').forEach(button=>button.addEventListener('click',()=>{const modal=document.getElementById('ai-modal-'+button.dataset.aiOpen);if(!modal)return;previousFocus=document.activeElement;modal.hidden=false;document.body.style.overflow='hidden';modal.querySelector('[data-ai-close]')?.focus()}));function close(modal){modal.hidden=true;document.body.style.overflow='';previousFocus?.focus()}overlays.forEach(modal=>{modal.querySelectorAll('[data-ai-close]').forEach(button=>button.addEventListener('click',()=>close(modal)));modal.addEventListener('click',e=>{if(e.target===modal)close(modal)})});document.addEventListener('keydown',e=>{if(e.key==='Escape')overlays.forEach(modal=>{if(!modal.hidden)close(modal)})})})();
</script>
